theorem periodic_shift_iterate {f : ℤ → ℝ} {n : ℕ} {p : ℝ}
    (hshift : ∀ j : ℤ, f (j + Int.ofNat n) = f j + p)
    (q j : ℤ) : f (j + q * Int.ofNat n) = f j + (q : ℝ) * p

theorem HasFLC.mono
    {E : Type*} [NormedAddCommGroup E] {S T : Set E}
    (hT : HasFLC T) (hST : S ⊆ T) : HasFLC S

theorem mem_of_locallyFellConverges_of_tendsto_mem
    {A : ℕ → Set Tiling.Plane} {L : Set Tiling.Plane}
    (hconv : Tiling.AxisParallel.Topology.LocallyFellConverges A L)
    {zseq : ℕ → Tiling.Plane} {z : Tiling.Plane}
    (hzmem : ∀ n, zseq n ∈ A n)
    (hzlim : Filter.Tendsto zseq Filter.atTop (nhds z)) : z ∈ L

theorem AffineSubspace.exists_affineLine_eq {L : AffineSubspace ℝ Plane} {a : Plane}
    (ha : a ∈ L) (hdim : Module.finrank ℝ L.direction = 1) :
    ∃ v : Plane, v ≠ 0 ∧ (L : Set Plane) = affineLine a v

theorem IsAxisParallel.exists_finite_boundary_axisLines {D : Set Plane}
    (hD : IsAxisParallel D) :
    ∃ V H : Finset ℝ, ∀ z ∈ frontier D, z.re ∈ V ∨ z.im ∈ H

theorem IsPolygonal.iUnion_closure_interiorComponents {s : Set Plane}
    (hs : IsPolygonal s) :
    (⋃ O ∈ interiorComponents s, closure O) = s

theorem IsPolygonal.interiorComponent_closure_isPolygonal {s O : Set Plane}
    (hs : IsPolygonal s) (hO : O ∈ interiorComponents s) :
    IsPolygonal (closure O)

theorem IsPolygonal.interiorComponent_frontier_eq {s O : Set Plane}
    (hs : IsPolygonal s) (hO : O ∈ interiorComponents s) :
    frontier O = frontier (closure O)

theorem IsPolygonal.interiorComponent_frontier_subset {s O : Set Plane}
    (hs : IsPolygonal s) (hO : O ∈ interiorComponents s) :
    frontier (closure O) ⊆ frontier s

theorem IsPolygonal.interiorComponent_interior_closure_eq {s O : Set Plane}
    (hs : IsPolygonal s) (hO : O ∈ interiorComponents s) :
    interior (closure O) = O

theorem IsRectangle.vadd {s : Set Plane}
    (hs : Tiling.IsRectangle s) (a : Plane) :
    Tiling.IsRectangle (a +ᵥ s)

theorem interiorComponent_basic {s O : Set Plane}
    (hO : O ∈ interiorComponents s) :
    IsOpen O ∧ IsConnected O ∧ O ⊆ interior s

theorem interiorComponent_closure_inter_interior_eq {s O : Set Plane}
    (hO : O ∈ interiorComponents s) :
    closure O ∩ interior s = O

theorem exists_placedVertex_on_invariant_contact_line [Finite P] {v : Plane}
    (hA : IsTiling A.prototiles A.placements) (hv : A.IsSlidingDirection v)
    {C D : A.Plate} (hCD : C ≠ D) {x : Plane}
    (hxC : x ∈ A.plateCarrier C) (hxD : x ∈ A.plateCarrier D) :
    ∃ (i : C) (t : ℝ), 1 ≤ t ∧
      t • v +ᵥ x ∈ A.placedVertexSet (i : A.placements)

theorem chooseBetween_complete {ls us : List ℚ} {z : ℚ}
    (hlower : ∀ l ∈ ls, l < z) (hupper : ∀ u ∈ us, z < u) :
    ∃ x, chooseBetween ls us = some x

theorem chooseBetween_sound {ls us : List ℚ} {x : ℚ}
    (h : chooseBetween ls us = some x) :
    (∀ l ∈ ls, l < x) ∧ (∀ u ∈ us, x < u)

theorem solveY_sound {qs : List StrictInequality} {x y : ℚ}
    (hx : SatisfiesAll1 (eliminateY qs) x) (hy : solveY qs x = some y) :
    SatisfiesAll qs (x, y)
